        lib.settings.fadeInSeconds=lib.settings.fadeOutSeconds=lib.settings.bufferSeconds=0;lib.settings.silenceMinSeconds=lib.settings.silenceMaxSeconds=0;lib.settings.jukeboxMode=JukeboxMode.OFF;
        lib.settings.menuFontId=lib.settings.widgetFontId="minecraft:default";lib.settings.menuBlur=false;mc.options.pauseOnLostFocus=false;
        root=mc.gameDirectory.toPath().toAbsolutePath().normalize().resolve("audit-fixtures/"+System.currentTimeMillis());Files.createDirectories(root);
        source=root.resolve("sender/Music/Album/original.wav");received=root.resolve("receiver/Renamed/renamed.wav");moved=root.resolve("moved/Renamed/renamed.wav");Files.createDirectories(source.getParent());Files.createDirectories(received.getParent());
        Files.copy(Path.of("../../fixtures/short.wav"),source);Files.copy(source,received);
        target=new Playlist("audit-target","Travel");other=new Playlist("audit-other","Other");target.enabled=other.enabled=false;target.includeVanilla=other.includeVanilla=false;lib.playlists.add(target);lib.playlists.add(other);
        old=new Track("file:audit_old",Path.of("../../fixtures/long.wav").toAbsolutePath().normalize().toString(),"Generated long",false);receiver=new Track("file:audit_receiver",received.toString(),"Generated short",false);lib.tracks.add(old);lib.tracks.add(receiver);lib.rebuildTrackIndex();target.tracks.put(old.id,true);target.tracks.put(receiver.id,false);lib.folders.add(new Folder(root.resolve("receiver").toString(),target.id));
        if(Boolean.getBoolean("afmr.probe.ridingAudit")){editor=new LibraryScreen(null,rt,target.id);ridingChecks();return;}
        var sender=new Library();sender.playlists.clear();var p=new Playlist("sender-a"," travel ");var q=new Playlist("sender-b","Audit incoming");p.enabled=q.enabled=false;p.includeVanilla=q.includeVanilla=false;p.volume=.37;p.finishCurrentSongOnExit=true;p.conditions.timeEnabled=true;p.conditions.startTime=100;p.conditions.endTime=900;
        var song=new Track("file:sender",source.toString(),"Shared generated",false);sender.tracks.add(song);sender.rebuildTrackIndex();p.tracks.put(song.id,false);q.tracks.put(song.id,true);sender.playlists.add(p);sender.playlists.add(q);sender.folders.add(new Folder(source.getParent().getParent().toString(),p.id));
        share=root.resolve("Audit shared setup.afmrp");themeFile=root.resolve("Audit theme.afmrt");editor=new LibraryScreen(null,rt,target.id);show(editor);rt.overridePlaylist(target.id,OverrideMode.UNTIL_RELEASED);
        var snapshot=PlaylistPresets.capture(sender,Set.of(p.id,q.id),true);rt.exportPresets(share,snapshot);
        await("Export and playing source",()->!rt.scanning()&&rt.engine().current()!=null,()->{check("Generated export exists",Files.isRegularFile(share));check("Export records content signatures",!PlaylistPresets.read(share).songs.getFirst().sha256.isEmpty());sequence=rt.engine().playbackSequence();importFile();});
        await("Default import destination",OvernightSuite::importReady,()->{check("Import defaults to New profile",field(current(),"destination")==null);check("Filename suggests profile name",((EditBox)field(current(),"profileName")).getValue().equals("Audit shared setup"));((EditBox)field(current(),"profileName")).setValue("Draft profile");click("Import songs");});
        await("Song lookup draft navigation",()->!rt.scanning()&&rt.presetSongPlan()!=null,()->{click("Find song files...");click("Show: Missing");check("All songs view lists generated track",((List<?>)field(current(),"rows")).size()==1);click("Show: All");check("Original folders view lists root",((List<?>)field(current(),"rows")).size()==1);click("Back to import");check("Profile name survives child screen",((EditBox)field(current(),"profileName")).getValue().equals("Draft profile"));var saved=current();show(null);show(saved);current().resize(current().width,current().height);check("Profile name survives hide and resize",((EditBox)field(current(),"profileName")).getValue().equals("Draft profile"));click("Cancel");check("Cancel creates no profile",lib.profiles.inactive.isEmpty());importFile();});
        await("Create imported-only profile",OvernightSuite::importReady,()->{((EditBox)field(current(),"profileName")).setValue("Audit imported");click("Create profile and import");check("One new inactive profile",lib.profiles.inactive.size()==1);var saved=lib.profiles.inactive.getFirst();importedProfile=saved.id;check("Imported profile contains imports only",saved.playlists.size()==2);check("New profile stays unbound and inactive",lib.profiles.activeId.equals(PlaylistProfiles.DEFAULT)&&lib.profiles.bindings.isEmpty());check("Settings-only new profile has no assignments",saved.playlists.stream().allMatch(x->x.tracks.isEmpty()));check("Import does not restart current song",sequence==rt.engine().playbackSequence());importFile();});
        await("Settings-only replacement",OvernightSuite::importReady,()->{click("Destination: New profile");check("Replacement and addition count",widget("Replace 1 / add 1").active);click("Replace 1 / add 1");check("Replacement retains object and priority",lib.playlists.indexOf(target)<lib.playlists.indexOf(other)&&lib.playlist(target.id)==target);check("Replacement updates volume and conditions",target.volume==.37&&target.conditions.timeEnabled);check("Settings-only retains enabled and disabled assignments",target.tracks.size()==2&&Boolean.TRUE.equals(target.tracks.get(old.id))&&Boolean.FALSE.equals(target.tracks.get(receiver.id)));check("Unrelated playlist remains",lib.playlist(other.id)==other);check("Replacement retains playing sequence",sequence==rt.engine().playbackSequence());importFile();});
        await("Individual content mismatch",OvernightSuite::importReady,()->{click("Destination: New profile");click("Import songs");});
        await("Choose mismatching file",()->!rt.scanning()&&rt.presetSongPlan()!=null,()->{String songId=rt.pendingPreset().data().songs.getFirst().id;rt.locatePresetFile(songId,Path.of(old.path));});
        await("Mismatch feedback",()->!rt.scanning(),()->{check("Wrong contents are rejected",rt.presetSongPlan().found()==0&&!rt.presetSongPlan().errors().isEmpty());rt.locatePresetFile(rt.pendingPreset().data().songs.getFirst().id,received);});
        await("Correct individual contents",()->!rt.scanning(),()->{check("Renamed identical file is verified",rt.presetSongPlan().found()==1&&rt.presetSongPlan().verified()==1);click("Find song files...");click("Show: Missing");var search=current().children().stream().filter(EditBox.class::isInstance).map(EditBox.class::cast).findFirst().orElseThrow();search.setValue("zz-no-such-song");check("Song search filters rows",((List<?>)field(field(current(),"list"),"items")).isEmpty());click("Back to import");click("Search linked libraries");});
