        await("Ambiguous name import rejected",OvernightSuite::importReady,()->{var duplicate=new Playlist("audit-ambiguous","TRAVEL");lib.playlists.add(duplicate);click("Destination: New profile");click("Replace 2 / add 0");check("Ambiguity keeps pending import",rt.pendingPreset()!=null&&rt.taskStatus().contains("not applied"));check("Ambiguity leaves existing playlist intact",lib.playlist(target.id)==target&&lib.playlists.contains(duplicate));lib.playlists.remove(duplicate);click("Cancel");while(lib.profiles.inactive.size()+1<PlaylistProfiles.LIMIT)lib.profiles.createImported("Limit "+lib.profiles.inactive.size(),new ArrayList<>());importFile();});
        await("Profile limit controls",OvernightSuite::importReady,()->{check("New-profile import disabled at limit",!widget("Create profile and import").active);click("Destination: New profile");check("Existing-profile import remains available at limit",widget("Replace 2 / add 0").active);click("Cancel");lib.profiles.inactive.removeIf(x->!x.id.equals(importedProfile));show(open("LibraryRepairScreen",editor,rt));click("Check again");});
        await("Completed health report",()->!rt.scanning()&&rt.sourceHealth()!=null,()->{priorReport=rt.sourceHealth();for(int i=0;i<5000;i++)lib.tracks.add(new Track("file:audit_missing_"+i,root.resolve("absent/"+i+".wav").toString(),"Missing "+i,false));lib.rebuildTrackIndex();click("Check again");current().tick();click("Cancel search");check("Cancellation enters cancelling state",rt.repairSearchCancelling());});
        await("Health cancellation acknowledged",()->!rt.scanning(),()->{check("Cancel keeps completed report object",rt.sourceHealth()==priorReport);check("No late repair preview",rt.pendingRepair()==null);lib.tracks.removeIf(t->t.id.startsWith("file:audit_missing_"));lib.rebuildTrackIndex();Files.createDirectories(moved.getParent());Files.move(received,moved);click("Check again");});
        await("Moved song reported",()->!rt.scanning(),()->{check("Moved generated song is marked missing",rt.sourceHealth().issues().stream().anyMatch(i->i.id().equals(receiver.id)));rt.prepareRepair(new LibraryRepair.Request(false,receiver.id,moved));});
        await("Repair preview cancellation",()->!rt.scanning()&&rt.pendingRepair()!=null&&current().getClass().getSimpleName().equals("RepairPreviewScreen"),()->{check("Repair verifies identical moved song",rt.pendingRepair().found()==1);click("Cancel");check("Cancel repair leaves old path",receiver.path.equals(received.toString()));rt.prepareRepair(new LibraryRepair.Request(false,receiver.id,moved));});
        await("Apply repair",()->!rt.scanning()&&rt.pendingRepair()!=null&&current().getClass().getSimpleName().equals("RepairPreviewScreen"),()->{click("Apply repair");check("Apply preserves disabled assignment",Boolean.FALSE.equals(target.tracks.get(receiver.id)));check("Apply changes path",lib.track(receiver.id).path.equals(moved.toString()));});
        await("Repair report refreshed",()->!rt.scanning(),()->{check("Repaired song clears missing issue",rt.sourceHealth().issues().stream().noneMatch(i->i.id().equals(receiver.id)));show(open("ThemesScreen",editor,rt));rt.themes().draft().menuColors.put(MenuColor.BACKGROUND,0x123456);themeId=rt.themes().saveCurrent("Audit colors");});
        add("Theme right-click and keyboard rename",()->{var list=(AbstractWidget)field(current(),"themes");int row=1;for(var theme:lib.settings.savedThemes){if(theme.id.equals(themeId))break;row++;}clickAt(list.getX()+15,list.getY()+row*14+7,InputConstants.MOUSE_BUTTON_RIGHT);check("Theme context menu is opaque",((List<?>)field(current(),"menu")).stream().allMatch(b->(boolean)field(b,"opaque")));key(InputConstants.KEY_DOWN);key(InputConstants.KEY_UP);key(InputConstants.KEY_RETURN);check("Keyboard opens Rename",current().getClass().getSimpleName().equals("ThemeNameScreen"));((EditBox)field(current(),"name")).setValue("Audit renamed");click("Rename");check("Theme renamed",ColorTheme.find(lib.settings,themeId).name.equals("Audit renamed"));rt.themes().exportFile(themeFile,rt.themes().snapshot("Audit renamed"));});
