    private static void widgetChecks()throws Exception{
        var image=new java.awt.image.BufferedImage(80,40,java.awt.image.BufferedImage.TYPE_INT_RGB);for(int x=0;x<80;x++)for(int y=0;y<40;y++)image.setRGB(x,y,x<40?0xE04040:0x40E040);Path png=root.resolve("widget.png");javax.imageio.ImageIO.write(image,"png",png.toFile());rt.widgetBackground().choose(png);
        await("Widget texture upload",()->!rt.widgetBackground().busy(),()->{check("Widget background owns uploaded texture",(boolean)field(rt.widgetBackground(),"uploaded"));show(open("CustomBackgroundScreen",editor,rt,CustomBackground.Target.WIDGET));var before=rt.menuBackground().name();click("Sizing:");check("Widget sizing is independent",rt.widgetBackground().fit()!=MenuImageLayout.Fit.FILL&&rt.menuBackground().name().equals(before));click("Preview");});
        add("Widget preview render",()->{shot("widget-preview");check("Widget preview opens",current().getClass().getSimpleName().equals("NowPlayingPreviewScreen"));current().onClose();Path bad=root.resolve("invalid.png");Files.writeString(bad,"not an image");rt.widgetBackground().choose(bad);});
        await("Bad widget image keeps prior image",()->!rt.widgetBackground().busy(),()->{check("Bad image retains previous name and texture",rt.widgetBackground().name().equals("widget.png")&&(boolean)field(rt.widgetBackground(),"uploaded"));click("Image");check("Widget disable releases textures",((Object[])field(rt.widgetBackground(),"textures")).length==0);click("Image");click("Preview");});
        await("Widget texture lazy reload",()->!rt.widgetBackground().busy()&&(boolean)field(rt.widgetBackground(),"uploaded"),()->{check("Widget re-enable reloads texture",((Object[])field(rt.widgetBackground(),"textures")).length==1);rt.widgetBackground().invalidate();});
        await("Widget resource reload",()->!rt.widgetBackground().busy()&&(boolean)field(rt.widgetBackground(),"uploaded"),()->{check("Widget invalidation recreates texture",((Object[])field(rt.widgetBackground(),"textures")).length==1);current().onClose();click("Reset image settings");check("Widget reset disables with default geometry",!rt.widgetBackground().enabled()&&rt.widgetBackground().fit()==MenuImageLayout.Fit.FILL&&rt.widgetBackground().opacity()==1);click("Back");var keys=Arrays.stream(mc.options.keyMappings).filter(k->k.getName().startsWith("key.afmr.")).toList();check("All sixteen keys share AFMR category",keys.size()==16&&keys.stream().map(k->k.getCategory()).distinct().count()==1);show(new net.minecraft.client.gui.screens.options.controls.KeyBindsScreen(editor,mc.options));});
        add("Controls category scroll",()->{var list=(net.minecraft.client.gui.screens.options.controls.KeyBindsList)field(current(),"keyBindsList");var entries=list.children();int first=-1,count=0;for(int i=0;i<entries.size();i++)if(entries.get(i).getClass().getSimpleName().equals("KeyEntry")&&((net.minecraft.client.KeyMapping)field(entries.get(i),"key")).getName().startsWith("key.afmr.")){if(first<0)first=i;count++;}check("Native controls list contains all fifteen AFMR rows",count==15);list.setScrollAmount(Math.max(0,first-1)*20);});
        add("Controls category render",()->{shot("controls");check("Native Key Binds screen opens",current().getClass().getSimpleName().equals("KeyBindsScreen"));show(null);command("summon minecraft:horse ~ ~ ~ {Tags:[\"afmr_audit_mount\"],Tame:1b}");});
        add("Mount horse",()->command("ride "+mc.player.getName().getString()+" mount @e[tag=afmr_audit_mount,type=minecraft:horse,limit=1,sort=nearest]"));
        await("Riding context observes horse",()->mc.player.isPassenger(),()->{check("Horse mount is observed as riding animal",rt.context().ridingAnimal());command("ride "+mc.player.getName().getString()+" dismount");});
        await("Dismount context",()->!mc.player.isPassenger(),()->{check("Dismount clears animal condition",!rt.context().ridingAnimal());command("kill @e[tag=afmr_audit_mount]");command("summon minecraft:oak_boat ~ ~ ~ {Tags:[\"afmr_audit_boat\"]}");});
        add("Mount boat",()->command("ride "+mc.player.getName().getString()+" mount @e[tag=afmr_audit_boat,limit=1,sort=nearest]"));
        await("Boat excluded",()->mc.player.isPassenger(),()->{check("Boat does not count as animal",!rt.context().ridingAnimal());command("ride "+mc.player.getName().getString()+" dismount");});
        add("Cleanup own mounts",()->{command("kill @e[tag=afmr_audit_boat]");check("FPS remains capped",mc.options.framerateLimit().get()<=60);rt.save();if(Boolean.getBoolean("afmr.probe.pickerAudit"))pickerChecks();});
    }
    private static boolean activeNativeSong(){var sound=(net.minecraft.client.resources.sounds.SoundInstance)field(field(rt.engine(),"audio"),"sound");return sound!=null&&mc.getSoundManager().isActive(sound);}
    private static void ridingChecks()throws Exception{
        if(Boolean.getBoolean("afmr.probe.multiplayer"))check("Riding audit uses separate loopback vanilla server",mc.getSingleplayerServer()==null&&mc.getCurrentServer()!=null&&mc.getCurrentServer().ip.equals("127.0.0.1:25575"));
        target.enabled=other.enabled=true;target.playOnTrigger=true;target.conditions.ridingAnimal=PlaylistConditions.State.YES;other.tracks.put(receiver.id,true);rt.engine().reset();
        show(open("PlaylistConditionsScreen",editor,rt,target,target.conditions,0));
        add("Paged riding control",()->{for(int i=0;i<30&&current().children().stream().filter(AbstractWidget.class::isInstance).map(AbstractWidget.class::cast).noneMatch(w->w.getMessage().getString().startsWith("Riding animal"));i++)click(">");var riding=widget("Riding animal");check("Paged condition exposes Riding animal",riding.visible);var edit=current().children().stream().filter(AbstractWidget.class::isInstance).map(AbstractWidget.class::cast).filter(w->w.getMessage().getString().equals(">")&&w.getY()==riding.getY()).findFirst().orElseThrow();click(edit);click("Not riding an animal");check("Not riding saves independently",target.conditions.ridingAnimal==PlaylistConditions.State.NO);click("Any");check("Any clears riding restriction",target.conditions.ridingAnimal==PlaylistConditions.State.ANY);click("Riding an animal");click("Back");click("Save & back");show(null);command("gamemode creative @s");});
        for(String animal:List.of("horse","donkey","mule","camel","pig","strider")){
            add("Summon "+animal,()->command("summon minecraft:"+animal+" ~ ~ ~ {Tags:[\"afmr_riding_test\"],Tame:1b}"));
            add("Nearby "+animal+" is insufficient",()->{check(animal+" nearby does not match",!rt.context().ridingAnimal());command("ride "+mc.player.getName().getString()+" mount @e[tag=afmr_riding_test,limit=1,sort=nearest]");});
            await("Mounted "+animal,()->mc.player.isPassenger()&&rt.context().ridingAnimal()&&target.id.equals(rt.engine().sourcePlaylistId())&&activeNativeSong(),()->{check(animal+" activates riding playlist with native song",rt.engine().current()!=null);command("ride "+mc.player.getName().getString()+" dismount");});
            await("Dismounted "+animal,()->!mc.player.isPassenger()&&!rt.context().ridingAnimal()&&other.id.equals(rt.engine().sourcePlaylistId()),()->{check(animal+" dismount returns to fallback",true);command("kill @e[tag=afmr_riding_test]");});
        }
        for(String vehicle:List.of("oak_boat","minecart")){
            add("Summon "+vehicle,()->command("summon minecraft:"+vehicle+" ~ ~ ~ {Tags:[\"afmr_riding_vehicle\"]}"));
            add("Mount "+vehicle,()->command("ride "+mc.player.getName().getString()+" mount @e[tag=afmr_riding_vehicle,limit=1,sort=nearest]"));
            await("Exclude "+vehicle,()->mc.player.isPassenger(),()->{check(vehicle+" remains fallback",!rt.context().ridingAnimal()&&other.id.equals(rt.engine().sourcePlaylistId()));command("ride "+mc.player.getName().getString()+" dismount");});
            await("Cleanup "+vehicle,()->!mc.player.isPassenger(),()->command("kill @e[tag=afmr_riding_vehicle]"));
        }
        add("Summon for dimension change",()->command("summon minecraft:horse ~ ~ ~ {Tags:[\"afmr_riding_teleport\"],Tame:1b}"));
        add("Mount before dimension change",()->command("ride "+mc.player.getName().getString()+" mount @e[tag=afmr_riding_teleport,limit=1]"));
        await("Mounted before change",()->rt.context().ridingAnimal(),()->command("execute in minecraft:the_nether run tp @s 0 100 0"));
        await("Dimension change clears riding",()->rt.context().dimension().equals("minecraft:the_nether")&&!mc.player.isPassenger()&&!rt.context().ridingAnimal()&&other.id.equals(rt.engine().sourcePlaylistId())&&activeNativeSong(),()->{check("Dimension transfer clears riding and uses fallback",other.id.equals(rt.engine().sourcePlaylistId()));command("execute in minecraft:overworld run tp @s 0 100 0");});
        await("Return from dimension",()->rt.context().dimension().equals("minecraft:overworld"),()->{command("kill @e[tag=afmr_riding_teleport]");check("Return does not restore stale riding state",!rt.context().ridingAnimal());command("summon minecraft:horse ~ ~ ~ {Tags:[\"afmr_riding_death\"],Tame:1b}");});
        add("Mount before death",()->command("ride "+mc.player.getName().getString()+" mount @e[tag=afmr_riding_death,limit=1]"));
        await("Riding before death",()->rt.context().ridingAnimal(),()->command("kill @s"));
        await("Death clears mount context",()->rt.context().dead()&&!rt.context().ridingAnimal(),()->{check("Death clears riding state",true);mc.player.respawn();});
        await("Respawn fallback",()->!rt.context().dead()&&!rt.context().ridingAnimal()&&other.id.equals(rt.engine().sourcePlaylistId())&&activeNativeSong(),()->{check("Respawn uses fallback without stale mount",true);command("kill @e[tag=afmr_riding_death]");rt.save();});
    }
    private static boolean pickerOpen(){try{var f=NativePicker.class.getDeclaredField("active");f.setAccessible(true);return f.get(null)!=null;}catch(Exception e){throw new RuntimeException(e);}}
    private static void pickerSignal(String phase,Path path)throws Exception{Files.writeString(root.resolve("../picker-request.txt").normalize(),phase+"\n"+(path==null?"":path)+"\n");log("PICKER "+phase+" "+path);}
    private static void pickerChecks()throws Exception{
        Path export=root.resolve("Explorer exported theme.afmrt");show(open("ThemesScreen",editor,rt));pickerSignal("save-theme",export);NativePicker.saveTheme(rt,rt.themes().snapshot("Explorer theme"));
        await("Explorer theme export",()->!pickerOpen()&&!rt.themes().busy(),()->{check("Native save callback writes chosen theme",Files.isRegularFile(export));themeCount=lib.settings.savedThemes.size();pickerSignal("open-theme",export);click("Import…");});
        await("Explorer theme import",()->!pickerOpen()&&!rt.themes().busy(),()->{check("Native open callback imports theme",lib.settings.savedThemes.size()==themeCount+1);pickerSignal("cancel-theme",null);click("Import…");});
        await("Explorer cancellation",()->!pickerOpen(),()->{check("Cancelling picker keeps themes unchanged",lib.settings.savedThemes.size()==themeCount+1);click("Cancel");importFile();});
        await("Explorer song chooser setup",OvernightSuite::importReady,()->click("Import songs"));
        await("Explorer song chooser",()->!rt.scanning()&&rt.presetSongPlan()!=null,()->{click("Find song files...");click("Show: Missing");var list=(AbstractWidget)field(current(),"list");clickAt(list.getX()+15,list.getY()+7,InputConstants.MOUSE_BUTTON_LEFT);pickerSignal("open-song",moved);click("Choose selected file...");});
        await("Explorer song identity",()->!pickerOpen()&&!rt.scanning(),()->{check("Native song chooser verifies contents",rt.presetSongPlan().found()==1&&rt.presetSongPlan().verified()==1);pickerSignal("open-folder",moved.getParent());click("Search a folder...");});
        await("Explorer folder search",()->!pickerOpen()&&!rt.scanning(),()->{check("Native folder search preserves verified match",rt.presetSongPlan().found()==1);click("Back to import");click("Cancel");show(open("CustomBackgroundScreen",editor,rt,CustomBackground.Target.WIDGET));pickerSignal("open-image",root.resolve("widget.png"));click("Choose image…");});
        await("Explorer widget image",()->!pickerOpen()&&!rt.widgetBackground().busy(),()->{check("Native image callback loads widget image",rt.widgetBackground().enabled()&&rt.widgetBackground().name().equals("widget.png"));pickerSignal("complete",null);});
    }
